INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-dakedenaku-1', 'sent-ex-dakedenaku-1', 'en', 'He is good not only at English but at cooking too.', 'authored'),
  ('st-ex-dakedenaku-2', 'sent-ex-dakedenaku-2', 'en', 'Not only is it cheap, it tastes good as well.', 'authored'),
  ('st-ex-dakedenaku-3', 'sent-ex-dakedenaku-3', 'en', 'Not just children — adults can enjoy it too.', 'authored'),
  ('st-ex-dakedenaku-4', 'sent-ex-dakedenaku-4', 'en', 'It was not only raining; the wind was strong as well.', 'authored'),
  ('st-ex-hodo-1', 'sent-ex-hodo-1', 'en', 'Today I am so tired I can hardly walk.', 'authored'),
  ('st-ex-hodo-2', 'sent-ex-hodo-2', 'en', 'There is nobody as kind as he is.', 'authored'),
  ('st-ex-hodo-3', 'sent-ex-hodo-3', 'en', 'I was so happy I could have cried.', 'authored'),
  ('st-ex-hodo-4', 'sent-ex-hodo-4', 'en', 'The more you study, the more you understand.', 'authored'),
  ('st-ex-kurai-1', 'sent-ex-kurai-1', 'en', 'That shop is close enough to walk to.', 'authored'),
  ('st-ex-kurai-2', 'sent-ex-kurai-2', 'en', 'I was sad enough to cry.', 'authored'),
  ('st-ex-kurai-3', 'sent-ex-kurai-3', 'en', 'I can manage that much.', 'authored'),
  ('st-ex-kurai-4', 'sent-ex-kurai-4', 'en', 'About half of it is left.', 'authored'),
  ('st-ex-toori-1', 'sent-ex-toori-1', 'en', 'Please make it the way the instructions say.', 'authored'),
  ('st-ex-toori-2', 'sent-ex-toori-2', 'en', 'It was just as I thought.', 'authored'),
  ('st-ex-toori-3', 'sent-ex-toori-3', 'en', 'I did as the teacher said.', 'authored'),
  ('st-ex-toori-4', 'sent-ex-toori-4', 'en', 'Just as expected, he won.', 'authored'),
  ('st-ex-mama-1', 'sent-ex-mama-1', 'en', 'I fell asleep with the window left open.', 'authored'),
  ('st-ex-mama-2', 'sent-ex-mama-2', 'en', 'Please do not come in with your shoes on.', 'authored'),
  ('st-ex-mama-3', 'sent-ex-mama-3', 'en', 'It is just as it always was.', 'authored'),
  ('st-ex-mama-4', 'sent-ex-mama-4', 'en', 'I ate standing up.', 'authored'),
  ('st-ex-kke-1', 'sent-ex-kke-1', 'en', 'Tomorrow is a day off, isn’t it?', 'authored'),
  ('st-ex-kke-2', 'sent-ex-kke-2', 'en', 'What was his name again?', 'authored'),
  ('st-ex-kke-3', 'sent-ex-kke-3', 'en', 'The exam is next week, right?', 'authored'),
  ('st-ex-kke-4', 'sent-ex-kke-4', 'en', 'Was there homework?', 'authored'),
  ('st-ex-ttequote-1', 'sent-ex-ttequote-1', 'en', 'He was saying he is not going.', 'authored'),
  ('st-ex-ttequote-2', 'sent-ex-ttequote-2', 'en', 'Apparently it is going to rain tomorrow.', 'authored'),
  ('st-ex-ttequote-3', 'sent-ex-ttequote-3', 'en', 'I heard the teacher is coming.', 'authored'),
  ('st-ex-ttequote-4', 'sent-ex-ttequote-4', 'en', 'I thought it was hopeless.', 'authored'),
  ('st-ex-nanka-1', 'sent-ex-nanka-1', 'en', 'Somebody like me could never do it.', 'authored'),
  ('st-ex-nanka-2', 'sent-ex-nanka-2', 'en', 'I do not want to eat vegetables or anything like that.', 'authored'),
  ('st-ex-nanka-3', 'sent-ex-nanka-3', 'en', 'I never expected him to come.', 'authored'),
  ('st-ex-nanka-4', 'sent-ex-nanka-4', 'en', 'I cannot believe I failed the exam.', 'authored'),
  ('st-ex-youniiu-1', 'sent-ex-youniiu-1', 'en', 'The teacher told the students to be quiet.', 'authored'),
  ('st-ex-youniiu-2', 'sent-ex-youniiu-2', 'en', 'My mother told me to come home early.', 'authored'),
  ('st-ex-youniiu-3', 'sent-ex-youniiu-3', 'en', 'The doctor told me to take the medicine.', 'authored'),
  ('st-ex-youniiu-4', 'sent-ex-youniiu-4', 'en', 'I told my little sister to tidy her room.', 'authored'),
  ('st-ex-saseteitadaku-1', 'sent-ex-saseteitadaku-1', 'en', 'I will take tomorrow off, if I may.', 'authored'),
  ('st-ex-saseteitadaku-2', 'sent-ex-saseteitadaku-2', 'en', 'Allow me to read the book.', 'authored'),
  ('st-ex-saseteitadaku-3', 'sent-ex-saseteitadaku-3', 'en', 'I will take my leave early today, if I may.', 'authored'),
  ('st-ex-saseteitadaku-4', 'sent-ex-saseteitadaku-4', 'en', 'I was allowed to use it.', 'authored')
