  ('sent-ex-dakedenaku-2', 'lang-ja', '値段が安いだけでなく、味もいい。', 'ねだん が やすい だけ で なく、あじ も いい。', 'lvl-ja-n3', 'authored', true),
  ('sent-ex-dakedenaku-3', 'lang-ja', '子供だけでなく、大人も楽しめる。', 'こども だけ で なく、おとな も たのしめる。', 'lvl-ja-n3', 'authored', true),
